content:
/* Reset & Global Settings */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --bg-primary: #f8fafc;
  --bg-surface: #ffffff;
  --bg-muted: #f1f5f9;
  --bg-hover: #e2e8f0;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --primary-light: #eff6ff;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-full: 9999px;
  --transition-fast: 0.15s ease;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  user-select: none;
  -webkit-user-select: none;
  overflow-x: hidden;
  touch-action: pan-y;
}

/* App Container */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1440px;
  margin: 0 auto;
  padding: 16px;
  gap: 16px;
}

/* Header Section */
.header-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8px 16px;
  background-color: var(--bg-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.app-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.025em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.app-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* Main Layout: Toolbar & Canvas */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex: 1;
}

@media (min-width: 860px) {
  .main-layout {
    flex-direction: row;
    align-items: flex-start;
  }
}

/* Toolbar Container */
.toolbar-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  width: 100%;
}

@media (min-width: 860px) {
  .toolbar-container {
    width: 280px;
    flex-shrink: 0;
  }
}

/* Tool Group */
.tool-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tool-group-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

/* Tool Buttons (Pen / Eraser) */
.tool-buttons {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.tool-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-main);
  background-color: var(--bg-muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.tool-btn:hover {
  background-color: var(--bg-hover);
}

.tool-btn-active {
  background-color: var(--primary-light);
  border-color: var(--primary-color);
  color: var(--primary-color);
  font-weight: 600;
}

/* Color Palette */
.color-palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  align-items: center;
}

.color-swatch {
  width: 100%;
  aspect-ratio: 1;
  max-width: 44px;
  max-height: 44px;
  margin: 0 auto;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-fast), border-color var(--transition-fast);
  padding: 0;
  outline: none;
}

.color-swatch:hover {
  transform: scale(1.1);
}

.color-swatch-active {
  border-color: var(--text-main);
  transform: scale(1.15);
  box-shadow: 0 0 0 2px var(--bg-surface), 0 0 0 4px var(--text-main);
}

/* Color Picker Input */
.color-picker-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.color-picker-input {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 36px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: transparent;
  cursor: pointer;
  padding: 2px;
}

.color-picker-input::-webkit-color-swatch-wrapper {
  padding: 0;
}

.color-picker-input::-webkit-color-swatch {
  border: none;
  border-radius: 4px;
}

/* Size Slider & Preview */
.size-slider-wrapper {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 4px 0;
}

.size-slider {
  width: 100%;
  accent-color: var(--primary-color);
  cursor: pointer;
}

.size-preview-dot {
  margin: 8px auto;
  border-radius: var(--radius-full);
  background-color: var(--text-main);
  transition: width 0.1s ease, height 0.1s ease, background-color 0.2s ease;
  min-width: 2px;
  min-height: 2px;
  max-width: 50px;
  max-height: 50px;
}

.size-value-label {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* Action Buttons */
.action-buttons {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: auto;
}

.action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background-color: var(--bg-muted);
  color: var(--text-main);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.action-btn:hover:not(:disabled) {
  background-color: var(--bg-hover);
}

.action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.action-btn-danger {
  color: var(--danger-color);
  background-color: var(--danger-light);
  border-color: transparent;
}

.action-btn-danger:hover:not(:disabled) {
  background-color: #fee2e2;
  color: var(--danger-hover);
}

.action-btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
  border-color: transparent;
  font-weight: 600;
}

.action-btn-primary:hover:not(:disabled) {
  background-color: var(--primary-hover);
}

/* Canvas Area */
.canvas-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 480px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  position: relative;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  flex: 1;
  min-height: 440px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #ffffff;
  touch-action: none;
}

.drawing-canvas {
  display: block;
  touch-action: none;
  cursor: crosshair;
  background-color: #ffffff;
  width: 100%;
  height: 100%;
}

/* Status Bar */
.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  font-size: 0.8125rem;
  color: var(--text-muted);
  box-shadow: var(--shadow-sm);
}

.status-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Mobile & Touch Optimizations */
@media (max-width: 600px) {
  .app-container {
    padding: 10px;
    gap: 10px;
  }

  .app-title {
    font-size: 1.25rem;
  }

  .canvas-area {
    min-height: 380px;
  }

  .color-palette {
    grid-template-columns: repeat(5, 1fr);
  }

  .color-swatch {
    max-width: 38px;
    max-height: 38px;
  }

  .status-bar {
    flex-direction: column;
    gap: 4px;
    align-items: flex-start;
  }
}

import type { RefObject } from 'react';

// 定数定義を constants.ts から re-export し後方互換性を保持
export { DEFAULT_PALETTE_COLORS, type PaletteColor } from './constants';

/**
 * 描画ツール種別（ペン / 消しゴム）
 */
export type DrawToolType = 'pen' | 'eraser';

/**
 * 描画ストローク内の座標と筆圧データ
 */
export interface DrawPoint {
  x: number;
  y: number;
  pressure?: number;
}

/**
 * 1ストローク（一筆）分の描画データ
 * キャンバス解像度やタイムスタンプ等の拡張メタデータを保持可能
 */
export interface StrokePath {
  id?: string;
  tool: DrawToolType;
  color: string;
  size: number;
  points: DrawPoint[];
  canvasWidth?: number;
  canvasHeight?: number;
  timestamp?: number;
}

/**
 * ツールバーコンポーネント用Props
 * 履歴操作（やり直し等）の拡張に対応
 */
export interface ToolbarProps {
  currentTool: DrawToolType;
  onToolChange: (tool: DrawToolType) => void;
  currentColor: string;
  onColorChange: (color: string) => void;
  currentSize: number;
  onSizeChange: (size: number) => void;
  onClear: () => void;
  onUndo: () => void;
  onSave: () => void;
  canUndo: boolean;
  onRedo?: () => void;
  canRedo?: boolean;
}

/**
 * お絵描きキャンバスコンポーネント用Props
 */
export interface CanvasBoardProps {
  currentTool: DrawToolType;
  currentColor: string;
  currentSize: number;
  strokes: StrokePath[];
  onStrokeComplete: (stroke: StrokePath) => void;
  canvasRef: RefObject<HTMLCanvasElement | null>;
}

import { ChangeEvent } from 'react';
import { Pen, Eraser, Undo, Redo, Trash2, Download } from 'lucide-react';
import { ToolbarProps, DEFAULT_PALETTE_COLORS } from '../types';

interface ExtendedToolbarProps extends ToolbarProps {
  onRedo?: () => void;
  canRedo?: boolean;
}

const SIZE_PRESETS = [
  { label: '細 (2px)', size: 2 },
  { label: '中 (6px)', size: 6 },
  { label: '太 (16px)', size: 16 },
  { label: '極太 (30px)', size: 30 },
] as const;

const Toolbar = ({
  currentTool,
  onToolChange,
  currentColor,
  onColorChange,
  currentSize,
  onSizeChange,
  onClear,
  onUndo,
  onSave,
  canUndo,
  onRedo,
  canRedo = false,
}: ExtendedToolbarProps) => {
  const handleSizeChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSizeChange(Number(e.target.value));
  };

  const handleCustomColorChange = (e: ChangeEvent<HTMLInputElement>) => {
    onColorChange(e.target.value);
  };

  // 全消去の誤操作防止確認ダイアログ
  const handleClearWithConfirm = () => {
    if (window.confirm('キャンバスの描画内容をすべて消去しますか？\nこの操作は取り消せません。')) {
      onClear();
    }
  };

  return (
    <aside className="toolbar-container" aria-label="描画ツール設定">
      {/* ツール選択（ペン / 消しゴム） */}
      <div className="tool-group">
        <span className="tool-group-title">ツール選択</span>
        <div className="tool-buttons">
          <button
            type="button"
            className={`tool-btn ${currentTool === 'pen' ? 'tool-btn-active' : ''}`}
            onClick={() => onToolChange('pen')}
            title="ペンで描く"
          >
            <Pen size={18} />
            <span>ペン</span>
          </button>
          <button
            type="button"
            className={`tool-btn ${currentTool === 'eraser' ? 'tool-btn-active' : ''}`}
            onClick={() => onToolChange('eraser')}
            title="消しゴムで消す"
          >
            <Eraser size={18} />
            <span>消しゴム</span>
          </button>
        </div>
      </div>

      {/* カラーパレット */}
      <div className="tool-group">
        <span className="tool-group-title">カラーパレット</span>
        <div className="color-palette">
          {DEFAULT_PALETTE_COLORS.map((color) => {
            const isSelected = currentTool === 'pen' && currentColor.toLowerCase() === color.toLowerCase();
            return (
              <button
                key={color}
                type="button"
                className={`color-swatch ${isSelected ? 'color-swatch-active' : ''}`}
                style={{ backgroundColor: color }}
                onClick={() => {
                  onColorChange(color);
                  if (currentTool !== 'pen') {
                    onToolChange('pen');
                  }
                }}
                title={color}
                aria-label={`色 ${color}`}
              />
            );
          })}
        </div>
        <div className="color-picker-wrapper">
          <input
            type="color"
            value={currentColor}
            onChange={handleCustomColorChange}
            className="color-picker-input"
            title="自由カラー選択"
            aria-label="カスタムカラー選択"
          />
        </div>
      </div>

      {/* 線の太さスライダー ＆ クイックプリセット */}
      <div className="tool-group">
        <span className="tool-group-title">線の太さ</span>
        <div className="size-slider-wrapper">
          <div
            className="size-preview-dot"
            style={{
              width: `${currentSize}px`,
              height: `${currentSize}px`,
              backgroundColor: currentTool === 'eraser' ? '#94a3b8' : currentColor,
            }}
          />
          <input
            type="range"
            min={1}
            max={50}
            value={currentSize}
            onChange={handleSizeChange}
            className="size-slider"
            aria-label="ペンの太さ"
          />
          <div className="size-value-label">{currentSize} px</div>

          {/* よく使う太さのクイックプリセットボタン */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '4px', marginTop: '4px' }}>
            {SIZE_PRESETS.map((preset) => (
              <button
                key={preset.size}
                type="button"
                className={`tool-btn ${currentSize === preset.size ? 'tool-btn-active' : ''}`}
                style={{ padding: '6px 2px', fontSize: '0.75rem' }}
                onClick={() => onSizeChange(preset.size)}
                title={`太さ ${preset.size}px に変更`}
              >
                {preset.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* 操作アクションボタン */}
      <div className="action-buttons">
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
          <button
            type="button"
            className="action-btn"
            onClick={onUndo}
            disabled={!canUndo}
            title="直前のストロークを取り消す (Ctrl+Z)"
          >
            <Undo size={16} />
            <span>1手戻す</span>
          </button>
          <button
            type="button"
            className="action-btn"
            onClick={() => onRedo?.()}
            disabled={!canRedo}
            title="取り消したストロークをやり直す"
          >
            <Redo size={16} />
            <span>やり直す</span>
          </button>
        </div>

        <button
          type="button"
          className="action-btn action-btn-danger"
          onClick={handleClearWithConfirm}
          title="キャンバス全体を白紙に戻す"
        >
          <Trash2 size={16} />
          <span>全消去</span>
        </button>

        <button
          type="button"
          className="action-btn action-btn-primary"
          onClick={onSave}
          title="キャンバスをPNG画像として保存"
        >
          <Download size={16} />
          <span>PNG保存</span>
        </button>
      </div>
    </aside>
  );
};

export default Toolbar;

import { useRef, useEffect, useCallback, PointerEvent } from 'react';
import { CanvasBoardProps, StrokePath, DrawPoint } from '../types';

// 論理基準解像度（リサイズ時にも絵が歪まずフィットするように管理）
const BASE_WIDTH = 800;
const BASE_HEIGHT = 600;

interface ViewportTransform {
  dpr: number;
  scale: number;
  offsetX: number;
  offsetY: number;
}

const CanvasBoard = ({
  currentTool,
  currentColor,
  currentSize,
  strokes = [],
  onStrokeComplete,
  canvasRef,
}: CanvasBoardProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isDrawingRef = useRef<boolean>(false);
  const currentPointsRef = useRef<DrawPoint[]>([]);
  const transformRef = useRef<ViewportTransform>({
    dpr: 1,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
  });

  // 論理座標系とRetinaスケーリングをCanvasコンテキストに適用
  const applyTransform = useCallback((ctx: CanvasRenderingContext2D) => {
    const { dpr, scale, offsetX, offsetY } = transformRef.current;
    ctx.setTransform(dpr * scale, 0, 0, dpr * scale, dpr * offsetX, dpr * offsetY);
  }, []);

  // 1ストロークをCanvasに描画する関数（ベジェ曲線補間）
  const renderSingleStroke = (ctx: CanvasRenderingContext2D, stroke: StrokePath) => {
    const { points, tool, color, size } = stroke;
    if (!points || points.length === 0) return;

    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (tool === 'eraser') {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.strokeStyle = 'rgba(0,0,0,1)';
      ctx.fillStyle = 'rgba(0,0,0,1)';
    } else {
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
    }

    if (points.length === 1) {
      const p = points[0];
      const radius = Math.max(1, (size * (p.pressure || 1)) / 2);
      ctx.beginPath();
      ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      return;
    }

    ctx.lineWidth = size;
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);

    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const curr = points[i];
      const midX = (prev.x + curr.x) / 2;
      const midY = (prev.y + curr.y) / 2;
      ctx.quadraticCurveTo(prev.x, prev.y, midX, midY);
    }

    const last = points[points.length - 1];
    ctx.lineTo(last.x, last.y);
    ctx.stroke();
    ctx.restore();
  };

  // 全ストロークの再描画
  const redrawAllStrokes = useCallback(
    (targetStrokes: StrokePath[]) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // 物理キャンバス全体をクリア
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // 論理座標変換を適用して描画
      applyTransform(ctx);

      for (const stroke of targetStrokes) {
        renderSingleStroke(ctx, stroke);
      }
    },
    [canvasRef, applyTransform]
  );

  // キャンバスサイズのレスポンシブ同期（devicePixelRatio & 論理スケール対応）
  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const updateCanvasSize = () => {
      const rect = container.getBoundingClientRect();
      const cssWidth = Math.max(300, Math.floor(rect.width));
      const cssHeight = Math.max(300, Math.floor(rect.height));
      const dpr = window.devicePixelRatio || 1;

      // 論理基準サイズに基づきアスペクト比を維持してスケーリング＆センタリング
      const scale = Math.min(cssWidth / BASE_WIDTH, cssHeight / BASE_HEIGHT);
      const offsetX = (cssWidth - BASE_WIDTH * scale) / 2;
      const offsetY = (cssHeight - BASE_HEIGHT * scale) / 2;

      transformRef.current = { dpr, scale, offsetX, offsetY };

      const physicalWidth = Math.round(cssWidth * dpr);
      const physicalHeight = Math.round(cssHeight * dpr);

      if (canvas.width !== physicalWidth || canvas.height !== physicalHeight) {
        canvas.width = physicalWidth;
        canvas.height = physicalHeight;
        canvas.style.width = `${cssWidth}px`;
        canvas.style.height = `${cssHeight}px`;
        redrawAllStrokes(strokes);
      }
    };

    updateCanvasSize();

    const resizeObserver = new ResizeObserver(() => {
      updateCanvasSize();
    });

    resizeObserver.observe(container);

    return () => {
      resizeObserver.disconnect();
    };
  }, [canvasRef, strokes, redrawAllStrokes]);

  // ストローク配列が更新されたら再描画
  useEffect(() => {
    redrawAllStrokes(strokes);
  }, [strokes, redrawAllStrokes]);

  // マウス/タッチ座標を論理座標系 (BASE_WIDTH x BASE_HEIGHT) に逆変換
  const getLogicalPoint = (e: PointerEvent<HTMLCanvasElement>): DrawPoint => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0, pressure: 1 };
    const rect = canvas.getBoundingClientRect();
    const { scale, offsetX, offsetY } = transformRef.current;

    const clientX = e.clientX - rect.left;
    const clientY = e.clientY - rect.top;

    const x = (clientX - offsetX) / scale;
    const y = (clientY - offsetY) / scale;
    const pressure = e.pressure && e.pressure > 0 ? e.pressure : 1;

    return { x, y, pressure };
  };

  const handlePointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.setPointerCapture(e.pointerId);

    isDrawingRef.current = true;
    const point = getLogicalPoint(e);
    currentPointsRef.current = [point];

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    applyTransform(ctx);

    // 最初の1点（タップ・クリックのドット）をベジェと整合する円で描画
    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (currentTool === 'eraser') {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.fillStyle = 'rgba(0,0,0,1)';
    } else {
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = currentColor;
    }

    const radius = Math.max(1, (currentSize * (point.pressure || 1)) / 2);
    ctx.beginPath();
    ctx.arc(point.x, point.y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };

  const handlePointerMove = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawingRef.current) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const point = getLogicalPoint(e);
    currentPointsRef.current.push(point);

    const pts = currentPointsRef.current;
    if (pts.length < 2) return;

    applyTransform(ctx);

    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = currentSize;

    if (currentTool === 'eraser') {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.strokeStyle = 'rgba(0,0,0,1)';
    } else {
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = currentColor;
    }

    // ドラッグ中も quadraticCurveTo による滑らかな曲線補間を実施
    if (pts.length === 2) {
      const p0 = pts[0];
      const p1 = pts[1];
      ctx.beginPath();
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo((p0.x + p1.x) / 2, (p0.y + p1.y) / 2);
      ctx.stroke();
    } else {
      const p0 = pts[pts.length - 3];
      const p1 = pts[pts.length - 2];
      const p2 = pts[pts.length - 1];
      const mid1X = (p0.x + p1.x) / 2;
      const mid1Y = (p0.y + p1.y) / 2;
      const mid2X = (p1.x + p2.x) / 2;
      const mid2Y = (p1.y + p2.y) / 2;

      ctx.beginPath();
      ctx.moveTo(mid1X, mid1Y);
      ctx.quadraticCurveTo(p1.x, p1.y, mid2X, mid2Y);
      ctx.stroke();
    }

    ctx.restore();
  };

  const finishDrawing = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawingRef.current) return;
    isDrawingRef.current = false;

    const canvas = canvasRef.current;
    if (canvas && canvas.hasPointerCapture(e.pointerId)) {
      canvas.releasePointerCapture(e.pointerId);
    }

    const pts = currentPointsRef.current;
    if (pts.length > 0) {
      // 最後のセグメントを終点まで滑らかにつなぐ
      if (pts.length >= 2 && canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) {
          applyTransform(ctx);
          ctx.save();
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.lineWidth = currentSize;

          if (currentTool === 'eraser') {
            ctx.globalCompositeOperation = 'destination-out';
            ctx.strokeStyle = 'rgba(0,0,0,1)';
          } else {
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = currentColor;
          }

          const prev = pts[pts.length - 2];
          const curr = pts[pts.length - 1];
          const midX = (prev.x + curr.x) / 2;
          const midY = (prev.y + curr.y) / 2;

          ctx.beginPath();
          ctx.moveTo(midX, midY);
          ctx.lineTo(curr.x, curr.y);
          ctx.stroke();
          ctx.restore();
        }
      }

      const newStroke: StrokePath = {
        tool: currentTool,
        color: currentColor,
        size: currentSize,
        points: [...pts],
      };
      onStrokeComplete(newStroke);
      currentPointsRef.current = [];
    }
  };

  return (
    <div className="canvas-area">
      <div className="canvas-wrapper" ref={containerRef}>
        <canvas
          ref={canvasRef}
          className="drawing-canvas"
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={finishDrawing}
          onPointerCancel={finishDrawing}
        />
      </div>
    </div>
  );
};

export default CanvasBoard;

import { useState, useRef, useEffect, useCallback } from 'react';
import Toolbar from './components/Toolbar';
import CanvasBoard from './components/CanvasBoard';
import { DrawToolType, StrokePath, DEFAULT_PALETTE_COLORS } from './types';

// CanvasBoard の基準解像度 (BASE_WIDTH: 800, BASE_HEIGHT: 600)
const BASE_WIDTH = 800;
const BASE_HEIGHT = 600;

// キャンバス中央基準で相対配置する初期デモイラストストローク生成関数
const createInitialDemoStrokes = (cx = BASE_WIDTH / 2, cy = BASE_HEIGHT / 2 - 20): StrokePath[] => [
  // 輪郭（イエローの円）
  {
    tool: 'pen',
    color: '#eab308',
    size: 6,
    points: [
      { x: cx - 60, y: cy - 70 },
      { x: cx - 20, y: cy - 85 },
      { x: cx + 20, y: cy - 85 },
      { x: cx + 60, y: cy - 70 },
      { x: cx + 85, y: cy - 25 },
      { x: cx + 85, y: cy + 25 },
      { x: cx + 60, y: cy + 70 },
      { x: cx + 20, y: cy + 85 },
      { x: cx - 20, y: cy + 85 },
      { x: cx - 60, y: cy + 70 },
      { x: cx - 85, y: cy + 25 },
      { x: cx - 85, y: cy - 25 },
      { x: cx - 60, y: cy - 70 },
    ],
  },
  // 左目
  {
    tool: 'pen',
    color: '#0f172a',
    size: 6,
    points: [
      { x: cx - 30, y: cy - 20 },
      { x: cx - 30, y: cy - 10 },
    ],
  },
  // 右目
  {
    tool: 'pen',
    color: '#0f172a',
    size: 6,
    points: [
      { x: cx + 30, y: cy - 20 },
      { x: cx + 30, y: cy - 10 },
    ],
  },
  // スマイルの口
  {
    tool: 'pen',
    color: '#ef4444',
    size: 5,
    points: [
      { x: cx - 40, y: cy + 25 },
      { x: cx - 20, y: cy + 45 },
      { x: cx + 20, y: cy + 45 },
      { x: cx + 40, y: cy + 25 },
    ],
  },
  // ポップなアンダーライン（青）
  {
    tool: 'pen',
    color: '#3b82f6',
    size: 8,
    points: [
      { x: cx - 110, y: cy + 120 },
      { x: cx - 40, y: cy + 130 },
      { x: cx + 40, y: cy + 115 },
      { x: cx + 110, y: cy + 125 },
    ],
  },
];

const App = () => {
  const [currentTool, setCurrentTool] = useState<DrawToolType>('pen');
  const [currentColor, setCurrentColor] = useState<string>(DEFAULT_PALETTE_COLORS[0]);
  const [currentSize, setCurrentSize] = useState<number>(6);
  const [strokes, setStrokes] = useState<StrokePath[]>(() => createInitialDemoStrokes());
  const [undoStack, setUndoStack] = useState<StrokePath[][]>([]);
  const [redoStack, setRedoStack] = useState<StrokePath[][]>([]);
  const [saveStatus, setSaveStatus] = useState<string>('');

  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // ストローク完了ハンドラ（履歴を保存し、やり直しスタックをクリア）
  const handleStrokeComplete = useCallback((newStroke: StrokePath) => {
    setStrokes((prev) => {
      setUndoStack((uPrev) => [...uPrev, prev]);
      return [...prev, newStroke];
    });
    setRedoStack([]);
  }, []);

  // 1手戻す（全消去直前や直前のストロークを取り消す）
  const handleUndo = useCallback(() => {
    setUndoStack((uPrev) => {
      if (uPrev.length === 0) return uPrev;
      const previousStrokes = uPrev[uPrev.length - 1];
      setStrokes((currentStrokes) => {
        setRedoStack((rPrev) => [...rPrev, currentStrokes]);
        return previousStrokes;
      });
      return uPrev.slice(0, -1);
    });
  }, []);

  // やり直し（取り消したストロークや全消去を取り消した状態を元に戻す）
  const handleRedo = useCallback(() => {
    setRedoStack((rPrev) => {
      if (rPrev.length === 0) return rPrev;
      const nextStrokes = rPrev[rPrev.length - 1];
      setStrokes((currentStrokes) => {
        setUndoStack((uPrev) => [...uPrev, currentStrokes]);
        return nextStrokes;
      });
      return rPrev.slice(0, -1);
    });
  }, []);

  // 全消去（現在のストロークをUndo履歴に退避してから白紙にする）
  const handleClear = useCallback(() => {
    setStrokes((prev) => {
      if (prev.length === 0) return prev;
      setUndoStack((uPrev) => [...uPrev, prev]);
      setRedoStack([]);
      return [];
    });
  }, []);

  // 高解像度 PNG画像保存ダウンロード（オフスクリーンで高精細レンダリング）
  const handleSave = useCallback(() => {
    // 基準解像度の2倍（1600x1200）の高精細キャンバスを作成
    const EXPORT_SCALE = 2;
    const exportWidth = BASE_WIDTH * EXPORT_SCALE;
    const exportHeight = BASE_HEIGHT * EXPORT_SCALE;

    const exportCanvas = document.createElement('canvas');
    exportCanvas.width = exportWidth;
    exportCanvas.height = exportHeight;
    const expCtx = exportCanvas.getContext('2d');

    if (!expCtx) return;

    // 白背景で塗りつぶし
    expCtx.fillStyle = '#ffffff';
    expCtx.fillRect(0, 0, exportWidth, exportHeight);

    // スケール適用してストロークを高品質描画
    expCtx.save();
    expCtx.scale(EXPORT_SCALE, EXPORT_SCALE);

    for (const stroke of strokes) {
      const { points, tool, color, size } = stroke;
      if (!points || points.length === 0) continue;

      expCtx.save();
      expCtx.lineCap = 'round';
      expCtx.lineJoin = 'round';

      if (tool === 'eraser') {
        // 白背景キャンバス上の消しゴム描画は白上書き
        expCtx.strokeStyle = '#ffffff';
        expCtx.fillStyle = '#ffffff';
      } else {
        expCtx.strokeStyle = color;
        expCtx.fillStyle = color;
      }

      if (points.length === 1) {
        const p = points[0];
        const radius = Math.max(1, (size * (p.pressure || 1)) / 2);
        expCtx.beginPath();
        expCtx.arc(p.x, p.y, radius, 0, Math.PI * 2);
        expCtx.fill();
        expCtx.restore();
        continue;
      }

      expCtx.lineWidth = size;
      expCtx.beginPath();
      expCtx.moveTo(points[0].x, points[0].y);

      for (let i = 1; i < points.length; i++) {
        const prev = points[i - 1];
        const curr = points[i];
        const midX = (prev.x + curr.x) / 2;
        const midY = (prev.y + curr.y) / 2;
        expCtx.quadraticCurveTo(prev.x, prev.y, midX, midY);
      }

      const last = points[points.length - 1];
      expCtx.lineTo(last.x, last.y);
      expCtx.stroke();
      expCtx.restore();
    }

    expCtx.restore();

    const dataUrl = exportCanvas.toDataURL('image/png');
    const link = document.createElement('a');
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    link.download = `oekaki-${timestamp}.png`;
    link.href = dataUrl;
    link.click();

    setSaveStatus('高解像度PNG画像を保存しました！');
    setTimeout(() => {
      setSaveStatus('');
    }, 3000);
  }, [strokes]);

  // キーボードショートカット (Undo: Ctrl/Cmd+Z, Redo: Ctrl/Cmd+Y または Ctrl/Cmd+Shift+Z)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const isCmdOrCtrl = e.ctrlKey || e.metaKey;
      if (!isCmdOrCtrl) return;

      const key = e.key.toLowerCase();
      if (key === 'z') {
        e.preventDefault();
        if (e.shiftKey) {
          handleRedo();
        } else {
          handleUndo();
        }
      } else if (key === 'y') {
        e.preventDefault();
        handleRedo();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleUndo, handleRedo]);

  return (
    <div className="app-container">
      {/* ヘッダーエリア */}
      <header className="header-section">
        <h1 className="app-title">🎨 お絵描きボード</h1>
        <p className="app-subtitle">
          マウス・指・タッチペンで直感的に描画できます。線の太さ・色変更・取り消し・やり直し・高解像度PNG保存に対応。
        </p>
      </header>

      {/* メインレイアウト（ツールバー ＋ キャンバス） */}
      <main className="main-layout">
        <Toolbar
          currentTool={currentTool}
          onToolChange={setCurrentTool}
          currentColor={currentColor}
          onColorChange={setCurrentColor}
          currentSize={currentSize}
          onSizeChange={setCurrentSize}
          onClear={handleClear}
          onUndo={handleUndo}
          onSave={handleSave}
          canUndo={undoStack.length > 0}
          onRedo={handleRedo}
          canRedo={redoStack.length > 0}
        />

        <CanvasBoard
          currentTool={currentTool}
          currentColor={currentColor}
          currentSize={currentSize}
          strokes={strokes}
          onStrokeComplete={handleStrokeComplete}
          canvasRef={canvasRef}
        />
      </main>

      {/* ステータスバー */}
      <footer className="status-bar">
        <div className="status-info">
          <span>
            現在のモード: <strong>{currentTool === 'pen' ? 'ペン描き' : '消しゴム'}</strong>
          </span>
          <span>太さ: <strong>{currentSize}px</strong></span>
          <span>ストローク数: <strong>{strokes.length}</strong></span>
        </div>
        <div className="status-info">
          {saveStatus ? (
            <span style={{ color: 'var(--primary-color)', fontWeight: 600 }}>{saveStatus}</span>
          ) : (
            <span>ショートカット: Ctrl + Z で戻す / Ctrl + Y (または Shift+Ctrl+Z) でやり直す</span>
          )}
        </div>
      </footer>
    </div>
  );
};

export default App;
